    if ask == 'and_your_brother_be_degraded_before_your_eyes':
        ink('25:3', "'AND YOUR BROTHER BE DEGRADED BEFORE YOUR EYES' — 'your brother' at 25:3 among the four chapters' brother-tokens (%s): once lashed he is your brother" % ([(c, v) for c, v in SPAN for x in W(c, v) if x == 'אחיך'],))
        move("the Sifrei 286:13-17 (read whole at the reading; 286:16 REREAD from chapter 12); MISHNAH MAKKOT 3:15 (the exam row, read whole); cold_run_sanctions (CALL) — SA.frame(lashes_discharge_karet) = %s ('once lashed he is your brother (Deut 25:3 [IMPORT])'), SA.frame(sit_and_abstain) = %s; cold_run_place_name (CALL) — the blood's cell 12:23's (PN read: %s)" % (SA_DISCH[0], SA_SIT[0], PN_INQ[1]), "'and your brother be degraded' — THE BROTHER RESTORED AND THE EXCISION LIFTED: all who are liable to karet (excision) who were lashed are exempt from their karet, 'and your brother be degraded before your eyes — once he is lashed he is your brother' — R. Chananya b. Gamliel (Makkot 3:15 — the exam row; 286:13-14 — the reading's find; sanctions' frame by CALL: THE LEVITICUS CELL READ 25:3 FORWARD); R. Shimon FROM ITS OWN PLACE — 'the souls that do shall be cut off' and 'which a man shall do and live': whoever sits and does not transgress is rewarded as one who did a commandment (3:15; sanctions' sit_and_abstain by CALL); R. Shimon b. Rabbi's a fortiori from the blood — if the blood, which a man's soul loathes, is rewarded for abstaining, how much more robbery and the unions (3:15 — 286:16 REREAD from chapter 12: 12:23's 'only be strong not to eat the blood', place_name's cell); karet_cut_off the kin's heaven entry, the discharge a HEAVEN reading — no new entry (SCANS %s)" % (SCANS['karet_cut_off'],))
        dat("THE WRITE brother_degradation_barred — a BLOCK on israel_people at the chapters' own day (DK2); the_karets_discharge a DATA row (Makkot 3:15 — the lashes discharge the karet, R. Chananya b. Gamliel; a heaven reading, no entry); the exam's person under karet who was lashed — his karet discharged, your brother again")
        return out("and your brother be degraded before your eyes (25:3) — once lashed he is your brother: the excision discharged, R. Chananya b. Gamliel; R. Shimon's reward for abstaining from its own place; the a fortiori from the blood (the Sifrei 286:13-17; Mishnah Makkot 3:15; sanctions' %s and place_name's blood by CALL): THE WRITE brother_degradation_barred, a BLOCK on Israel at the chapters' own day; the lashed man's karet discharged" % (SA_DISCH[0][0],), ['brother_degradation_barred'])
    if ask == 'you_shall_not_muzzle_an_ox':
        ink('25:4', "'YOU SHALL NOT MUZZLE AN OX IN ITS TREADING' — no verse of the Bible shares two of its words (KINC %s); 25:4 shares %d tokens with Genesis 13:7 (the muzzled beasts' seat — the spine's citation at 286:1)" % (KINC[(25, 4)], TWIN['25:4 vs Gen 13:7']))
