    if ask == 'the_shoe_and_the_spittle':
        ink('25:9', "'Then his brother's wife shall come near to him before the eyes of the elders AND DRAW OFF HIS SHOE FROM HIS FOOT AND SPIT IN HIS FACE, and answer and say: SO SHALL IT BE DONE TO THE MAN who does not build his brother's house' — 'answer and say' 27:14-15's Levites' formula (25:9 shares %d token with 27:15 — THE RECITAL AHEAD, the reading's find); Onkelos 'his shoe' and 'and she shall spit'; 25:9 shares %d token with Ruth 4:7 (the former custom)" % (TWIN['25:9 vs 27:15'], TWIN['25:9 vs Ruth 4:7']))
